/** 懒加载图标库的 gzip+base64 原文（浏览器里用 DecompressionStream 解） */
export const ICON_GZ_B64: Record<string, string> = {
  lucide: "",
  tabler: "",
};
/** 解压某套懒加载图标库（首次调用 80~250ms，之后走缓存）；Node/无 DecompressionStream 环境返回 null */
export function decompressIconSet(name: "lucide" | "tabler"): Promise<IconItem[]> | null {
  if (typeof globalThis.DecompressionStream === "undefined") return null;
  const b64 = ICON_GZ_B64[name];
  if (!b64) return Promise.resolve([]);
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"));
  return new Response(stream).text().then((txt) => {
    const arr = JSON.parse(txt) as IconItem[];
    for (const it of arr) {
      it.st = 1;
      it.c = CAT_ALIAS[it.c] || it.c;
    }
    return arr;
  });
}
